const cfg = $('Buscar credenciais empresa ação').item.json;
const store = $getWorkflowStaticData('global');
store.food99Tokens = store.food99Tokens || {};
const cached = store.food99Tokens[cfg.id_loja_plataforma];
const valido = !!(cached && cached.expiresAt > Date.now() + 60000);
return [{ json: { app_id_valor: cfg.api_key, app_shop_id_valor: cfg.id_loja_plataforma, api_secret: cfg.api_secret, auth_token: valido ? cached.authToken : null, token_valido: valido } }];

const ctx = $('Checar token 99Food em cache (ação99)').item.json;
const resp = $json;
const tokenData = resp.data || {};
const ok = resp.errno === 0 && !!tokenData.auth_token;
const store = $getWorkflowStaticData('global');
store.food99Tokens = store.food99Tokens || {};
if (ok) { store.food99Tokens[ctx.app_shop_id_valor] = { authToken: tokenData.auth_token, expiresAt: tokenData.token_expiration_time ? tokenData.token_expiration_time * 1000 : Date.now() + 21600000 }; }
return [{ json: { ...ctx, auth_token: ok ? tokenData.auth_token : null, token_valido: ok, token_erro: ok ? null : (resp.errmsg || 'erro desconhecido ao obter token') } }];

const w = $('Webhook Ação').item.json.body;
// 99Food (Adjust Order Items) so cobre cancelar/marcar esgotado/ajustar peso --
// NAO EXISTE operacao de "substituir por outro produto" como no iFood (que
// insere um item novo no lugar). Pra 'substituir', a unica coisa possivel e
// cancelar o item original -- o cliente fica sem substituto real, so um
// estorno parcial. Isso fica logado explicitamente, nao finge que funcionou.
const isSubstituicaoSemSuporte = w.tipo_acao === 'substituir';
const body = {
  auth_token: $json.auth_token,
  order_id: w.marketplace_order_id,
  cancel: {
    items: [{
      mdu_id: w.uniqueid_marketplace,
      cancel_amount: w.quantidade,
    }],
  },
};
return [{ json: { ...$json, body, isSubstituicaoSemSuporte } }];
